query TeacherClassrooms($teacherId: String) {
  teacherClassrooms(teacherId: $teacherId) {
    id
    name
    digit
    grade
    gradeName
    schoolShortName
    schoolUuid
    students {
      ...classroomStudentFragment
    }
    isEducont
  }
}

fragment classroomStudentFragment on ClassroomStudent {
  id
  invitationAccepted
  invitationCode
  name
  studentUserId
  educontUid
}
